/**
 * READ-ONLY measurement: "How much extra system-prompt does adopting OpenUI cost,
 * if the component library is the FULL shadcn/ui set?"
 *
 * Baseline = a default AI SDK project with NO system prompt = 0 tokens.
 * So "extra tokens" == the whole OpenUI system prompt we would have to inject.
 *
 * Three (four) tiers, ALL generated by the REAL OpenUI prompt assembler
 * (`createLibrary().prompt()` / `generateSystemPrompt()` from the installed
 * `@openuidev/lang-core@0.3.0` — the exact package apps/compare uses):
 *
 *   A. empty skeleton   0 components  (OpenUI syntax rules only)
 *   B. demo today       8 components  (apps/compare 8 Shadcn-backed blocks)
 *   C. full shadcn/ui  60 components  (our 60 `ui.*` contracts)
 *   C+ full catalog    67 components  (60 `ui.*` + 7 core/layout contracts, root = LayoutStack)
 *
 * The C tiers are a MECHANICAL conversion, not OpenUI's own library:
 *   contract.resolvedPropsSchema  ->  JSON Schema
 *     -> z.fromJSONSchema()       ->  ZodObject
 *       -> defineComponent()      ->  OpenUI signature (via analyzeFields/buildSignature)
 *         -> createLibrary().prompt()
 * No signature is hand-written.
 *
 * Run (needs the monorepo on disk for workspace imports + node_modules):
 *   cd /Users/work/open-generative && bun \
 *     /Users/work/ai/notes/generative-ui/future/catalog-tokens-runs/openui-full-shadcn.ts
 *
 * Prompt .txt outputs land in /tmp/oui-adoption/ for the tokenizer pass.
 * Nothing under /Users/work/open-generative is written.
 */
import { writeFileSync, mkdirSync } from "node:fs";

// Pin to the EXACT packages apps/compare uses (bun would otherwise resolve the
// bare specifier "@openuidev/lang-core" from its global cache at v1.0.0).
const REPO = "/Users/work/open-generative";
const { z } = await import(`${REPO}/apps/compare/node_modules/zod/index.js`);
const { createLibrary, defineComponent, generateSystemPrompt } = await import(
  `${REPO}/apps/compare/node_modules/@openuidev/lang-core/dist/index.mjs`,
);

import { createOfficialCatalog } from "/Users/work/open-generative/packages/components/src/contracts.ts";
import { schemaLibrary as demoLibrary } from "/Users/work/open-generative/apps/compare/src/lib/openui/definitions.ts";

const OUT = "/tmp/oui-adoption";
mkdirSync(OUT, { recursive: true });

const utf8 = (s: string) => new TextEncoder().encode(s).byteLength;
const chars = (s: string) => [...s].length;

/** The exact prompt options apps/compare sends (prompt.ts). */
const ADDITIONAL_RULES = [
  "Respond only with OpenUI Lang assignment statements. Never output Markdown, JSX, HTML, CSS, or code fences.",
  "Every response must assign root exactly once using Screen(title, subtitle, children).",
  "Use only components in the supplied library. Compose several small Shadcn components instead of writing custom markup.",
  "Match the user's language. Keep generated text concise and useful.",
  "Use CardBlock for structured results, BadgeBlock for tags, InputBlock for forms, ButtonBlock for actions, ListBlock for recommendations, and TableBlock for comparisons.",
];
const OPTIONS = { bindings: false, toolCalls: false, additionalRules: ADDITIONAL_RULES } as const;
const OPTIONS_BARE = { bindings: false, toolCalls: false } as const;

// ─── section breakdown (same "## " splitter used in oui_prompt_reproduce.sh) ───
function sections(prompt: string) {
  const lines = prompt.split("\n");
  const marks: { title: string; line: number }[] = [];
  lines.forEach((l, i) => {
    if (l.startsWith("## ")) marks.push({ title: l.slice(3).trim(), line: i });
  });
  const first = marks.length ? marks[0].line : lines.length;
  const out = [{ title: "(preamble)", text: lines.slice(0, first).join("\n") }];
  for (let i = 0; i < marks.length; i++) {
    const end = i + 1 < marks.length ? marks[i + 1].line : lines.length;
    out.push({ title: marks[i].title, text: lines.slice(marks[i].line, end).join("\n") });
  }
  return out;
}

const rows: { tier: string; comps: number; prompt: string; file: string }[] = [];

function record(tier: string, comps: number, prompt: string, file: string) {
  writeFileSync(`${OUT}/${file}.txt`, prompt);
  rows.push({ tier, comps, prompt, file });
  const t = sections(prompt);
  const sig = t.find((s) => s.title === "Component Signatures");
  console.log(
    `${tier.padEnd(34)} comps=${String(comps).padStart(3)} chars=${String(chars(prompt)).padStart(7)} bytes=${String(utf8(prompt)).padStart(7)} lines=${String(prompt.split("\n").length).padStart(4)} sigSection=${sig ? chars(sig.text) : 0}`,
  );
  return t;
}

// ─── A. empty skeleton ───────────────────────────────────────────────────────
const emptyPrompt = generateSystemPrompt({
  library: { root: "Stack", components: {} },
  promptOptions: OPTIONS,
} as never);
record("A. empty skeleton (0)", 0, emptyPrompt, "A-empty");

// ─── B. the demo's real 8-block library ─────────────────────────────────────
const bPrompt = demoLibrary.prompt(OPTIONS);
record("B. demo today (8 blocks)", Object.keys(demoLibrary.components).length, bPrompt, "B-demo8");

// ─── C. mechanical conversion of our contracts ──────────────────────────────
const official = await createOfficialCatalog();
const all = official.componentContracts;

/** `ui.alert-dialog` -> `AlertDialog` (OpenUI uses bare PascalCase names);
 *  `layout.stack` -> `LayoutStack` (non-ui namespaces keep their prefix). */
function pascal(type: string): string {
  const base = type.startsWith("ui.") ? type.slice(3) : type;
  return base
    .split(/[.\-]/)
    .filter(Boolean)
    .map((p) => p[0].toUpperCase() + p.slice(1))
    .join("");
}

/** JSON Schema -> ZodObject. Drops $schema/$defs (this repo's prop schemas are self-contained). */
function toZodObject(schema: unknown): z.ZodObject | null {
  if (!schema || typeof schema !== "object") return null;
  const clean: Record<string, unknown> = { ...(schema as Record<string, unknown>) };
  delete clean.$schema;
  delete clean.$defs;
  try {
    const zs = (z as unknown as { fromJSONSchema: (s: unknown) => unknown }).fromJSONSchema(clean);
    if (!zs || typeof zs !== "object" || !("shape" in (zs as object))) return null;
    return zs as z.ZodObject;
  } catch {
    return null;
  }
}

type Built = { name: string; type: string; description: string; ok: boolean };
const skipped: string[] = [];

/** Realistic "shortest readable form": an enum of icon names or colours is not
 *  something you want to spell out to the model. Collapse enums with more than
 *  `maxEnum` literals down to `string`. */
function leanify(schema: any, maxEnum: number): any {
  const clone = (node: any): any => {
    if (Array.isArray(node)) return node.map(clone);
    if (!node || typeof node !== "object") return node;
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(node)) {
      if (k === "enum" && Array.isArray(v) && v.length > maxEnum) {
        out.type = "string";
        continue;
      }
      out[k] = clone(v);
    }
    if (!("type" in out) && !("enum" in out) && !("anyOf" in out) && !("oneOf" in out) && !("$ref" in out)) {
      out.type = out.type ?? undefined;
    }
    return out;
  };
  return clone(schema);
}

function buildLibrary(
  contracts: readonly any[],
  id: string,
  rootType: string,
  withUseWhen: boolean,
  maxEnum = Number.POSITIVE_INFINITY,
) {
  const comps: any[] = [];
  const built: Built[] = [];
  for (const c of contracts) {
    const type: string = c.ref.componentType;
    const name = pascal(type);
    const source =
      maxEnum === Number.POSITIVE_INFINITY ? c.resolvedPropsSchema : leanify(c.resolvedPropsSchema, maxEnum);
    const props = toZodObject(source);
    if (!props) {
      skipped.push(type);
      continue;
    }
    const summary = String(c.prompt?.summary ?? "");
    const useWhen = (c.prompt?.useWhen ?? []) as readonly string[];
    const description = withUseWhen && useWhen.length ? `${summary} ${useWhen.join(" ")}` : summary;
    comps.push(defineComponent({ name, props, description, component: null }));
    built.push({ name, type, description, ok: true });
  }
  const root = pascal(rootType);
  const lib = createLibrary({ id, root, components: comps });
  return { lib, built };
}

const uiContracts = all.filter((c) => c.ref.componentType.startsWith("ui."));
const coreContracts = all.filter((c) => !c.ref.componentType.startsWith("ui."));

// C1: pure 60 shadcn ui.* contracts. OpenUI's createLibrary() requires `root` to
// be one of the components, so the catalog's own layout root (`layout.stack`)
// is added as the 61st definition — exactly like OpenUI's own library ships
// `Stack` inside its 82. Documented, not hidden.
const c1 = buildLibrary([...uiContracts, ...coreContracts.filter((c) => c.ref.componentType === "layout.stack")], "shadcn-ui-full", "layout.stack", false);
const c1Prompt = c1.lib.prompt(OPTIONS);
record("C1. full shadcn ui.* (60)", c1.built.length, c1Prompt, "C1-shadcn60");

// C2: same 60, but descriptions include `prompt.useWhen` (our full model-facing prose).
const c2 = buildLibrary([...uiContracts, ...coreContracts.filter((c) => c.ref.componentType === "layout.stack")], "shadcn-ui-full-usewhen", "layout.stack", true);
const c2Prompt = c2.lib.prompt(OPTIONS);
record("C2. full shadcn ui.* + useWhen", c2.built.length, c2Prompt, "C2-shadcn60-usewhen");

// C3: whole official catalog = 60 ui.* + 7 core/layout (root = LayoutStack component).
const c3 = buildLibrary(all, "official-catalog-67", "layout.stack", false);
const c3Prompt = c3.lib.prompt(OPTIONS);
record("C3. full catalog (67)", c3.built.length, c3Prompt, "C3-full67");

// C4: same as C1 but enums longer than 10 literals collapse to `string`.
const leanContracts = [...uiContracts, ...coreContracts.filter((c) => c.ref.componentType === "layout.stack")];
const c4 = buildLibrary(leanContracts, "shadcn-ui-lean", "layout.stack", false, 10);
const c4Prompt = c4.lib.prompt(OPTIONS);
record("C4. shadcn ui.* LEAN (enum>10 -> string)", c4.built.length, c4Prompt, "C4-shadcn-lean");

// ─── additionalRules = [] variants, to isolate the catalog cost ─────────────
console.log("\n-- same, with additionalRules: [] (isolates the catalog) --");
const bare: { tier: string; comps: number }[] = [];
for (const [tier, comps, prompt] of [
  ["A. empty skeleton (0)", 0, generateSystemPrompt({ library: { root: "Stack", components: {} }, promptOptions: OPTIONS_BARE } as never)],
  ["B. demo today (8)", Object.keys(demoLibrary.components).length, demoLibrary.prompt(OPTIONS_BARE)],
  ["C1. full shadcn ui.* (60)", c1.built.length, c1.lib.prompt(OPTIONS_BARE)],
] as const) {
  writeFileSync(`${OUT}/${tier.split(".")[0]}-bare.txt`, prompt as string);
  bare.push({ tier: tier as string, comps: comps as number });
  console.log(
    `${(tier as string).padEnd(34)} comps=${String(comps).padStart(3)} chars=${String(chars(prompt as string)).padStart(7)} bytes=${String(utf8(prompt as string)).padStart(7)}`,
  );
}

// ─── signature detail for the notes ────────────────────────────────────────
const c1Spec = c1.lib.toSpec() as any;
const sigs = Object.entries(c1Spec.components as Record<string, { signature: string; description?: string }>);
const sigChars = sigs.reduce((n, [, v]) => n + chars(v.signature), 0);
const descChars = sigs.reduce((n, [, v]) => n + chars(v.description ?? ""), 0);
console.log("\n-- C1 signature detail --");
console.log(`components=${sigs.length}  signature-chars=${sigChars}  avg=${(sigChars / sigs.length).toFixed(1)}`);
console.log(`description-chars=${descChars}  avg=${(descChars / sigs.length).toFixed(1)}`);

const c1Sections = sections(c1Prompt);
const c1SigSection = c1Sections.find((s) => s.title === "Component Signatures");
console.log(`C1 "Component Signatures" section chars = ${c1SigSection ? chars(c1SigSection.text) : 0}`);
console.log(`C1 section list: ${c1Sections.map((s) => `${s.title}=${chars(s.text)}`).join("  ")}`);

console.log(`\nC3 skipped (JSON-Schema->Zod failed): ${skipped.length ? skipped.join(", ") : "none"}`);
console.log(`C1 component names: ${c1.built.map((b) => b.name).join(", ")}`);

// longest / shortest signatures, useful for the notes
const sorted = sigs.map(([n, v]) => [n, chars(v.signature)] as const).sort((a, b) => b[1] - a[1]);
console.log("\nlongest signatures:", sorted.slice(0, 5).map(([n, c]) => `${n}=${c}`).join(", "));
console.log("shortest signatures:", sorted.slice(-5).map(([n, c]) => `${n}=${c}`).join(", "));

// ─── manifest for the tokenizer pass ────────────────────────────────────────
const manifest = {
  generatedFrom: "createOfficialCatalog() + @openuidev/lang-core@0.3.0 (apps/compare install)",
  tiers: rows.map((r) => ({
    tier: r.tier,
    file: `${r.file}.txt`,
    components: r.comps,
    chars: chars(r.prompt),
    bytes: utf8(r.prompt),
    signatureSectionChars: (() => {
      const s = sections(r.prompt).find((x) => x.title === "Component Signatures");
      return s ? chars(s.text) : 0;
    })(),
  })),
  c1: {
    componentNames: c1.built.map((b) => b.name),
    signatureChars: sigChars,
    descriptionChars: descChars,
    longest: sorted.slice(0, 8).map(([n, c]) => ({ name: n, chars: c })),
  },
  skipped,
};
writeFileSync(`${OUT}/manifest.json`, JSON.stringify(manifest, null, 2));
console.log("\nmanifest: " + OUT + "/manifest.json");
console.log("Prompt files: " + OUT + "/*.txt");
